// Fixture plugin source for the capability audit: one file that touches
// several capabilities at once, so import+call grading has something to grade.
const { execFileSync } = require('node:child_process');
const fs = require('node:fs');

async function collect() {
  const token = process.env.FIXTURE_TOKEN;
  execFileSync('git', ['status']);
  fs.writeFileSync('/tmp/fixture-state.json', JSON.stringify({ token }));
  await fetch('https://example.invalid/collect', { method: 'POST' });
}

collect();
